import { describe, expect, it } from 'vitest';
import { exportSql } from '@/formats/sql/export-sql';
import { sampleS1, sampleS2, sampleS3 } from './testing/sample-designs';

const lines = (...l: string[]) => l.join('\n');

describe('EXP-006 EXP-046 converter samples', () => {
    it('PostgreSQL S1 to MySQL', () => {
        expect(exportSql(sampleS1('postgresql'), 'mysql').text).toBe(
            lines(
                '-- PostgreSQL to MySQL conversion',
                '-- Generated by QBase',
                '',
                'CREATE TABLE `customers` (',
                '    `id` INT NOT NULL AUTO_INCREMENT,',
                '    `email` VARCHAR(120) NOT NULL UNIQUE,',
                '    `full_name` VARCHAR(80),',
                '    `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,',
                '    PRIMARY KEY (`id`)',
                ');',
                '',
                'CREATE TABLE `orders` (',
                '    `id` INT NOT NULL AUTO_INCREMENT,',
                '    `customer_id` INT NOT NULL,',
                '    `total` DECIMAL(10, 2) NOT NULL DEFAULT 0,',
                '    PRIMARY KEY (`id`)',
                ');',
                '',
                '-- Indexes',
                'CREATE INDEX `idx_orders_customer` ON `orders` (`customer_id`);',
                '',
                '-- Foreign key constraints',
                'ALTER TABLE `orders` ADD CONSTRAINT `fk_orders_customers` FOREIGN KEY (`customer_id`) REFERENCES `customers` (`id`);',
                ''
            )
        );
    });
    it('EXP-039 EXP-045 EXP-047 PostgreSQL S3 to SQLite (notes, Was comment, enum CHECK, gin index)', () => {
        expect(exportSql(sampleS3('postgresql'), 'sqlite').text).toBe(
            lines(
                '-- PostgreSQL to SQLite conversion',
                '-- Generated by QBase',
                '--',
                '-- CONVERSION NOTES (3 items):',
                '--',
                '-- Type conversions:',
                '--   - tickets.tags: text is an array',
                '--   - tickets.tags: stored as JSON text',
                '--',
                '-- Indexes:',
                '--   - tickets.idx_tickets_tags: gin index created as a regular index',
                '--',
                '',
                'CREATE TABLE "tickets" (',
                '    "id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,',
                `    "status" TEXT NOT NULL DEFAULT 'open',`,
                '    "tags" TEXT, -- Was: text',
                `    "payload" TEXT DEFAULT '{}',`,
                '    "title" VARCHAR(200) NOT NULL UNIQUE,',
                `    CHECK ("status" IN ('open', 'closed', 'it''s done'))`,
                ');',
                '',
                '-- Indexes',
                'CREATE INDEX "idx_tickets_tags" ON "tickets" ("tags");',
                'CREATE UNIQUE INDEX "uq_tickets_status_title" ON "tickets" ("status", "title");',
                ''
            )
        );
    });
});

describe('EXP-037 EXP-040 EXP-041 EXP-042 EXP-043 EXP-044 EXP-048 converter rules', () => {
    it('EXP-046 SQLite prefixes schema names, MySQL writes databases, SQL Server writes schemas', () => {
        const s2 = sampleS2('postgresql');
        const sqlite = exportSql(s2, 'sqlite').text;
        expect(sqlite).toContain('CREATE TABLE "school_courses"');
        expect(sqlite).toContain(
            'FOREIGN KEY ("course_code") REFERENCES "school_courses" ("code")'
        );
        expect(sqlite).toContain('SQLite has no schemas');
        expect(exportSql(s2, 'mysql').text).toContain(
            'CREATE DATABASE IF NOT EXISTS `school`;'
        );
        expect(exportSql(s2, 'sql_server').text).toContain(
            "EXEC('CREATE SCHEMA [school]')"
        );
    });
    it('EXP-037 types map per target', () => {
        const mysql = exportSql(sampleS2('postgresql'), 'mysql').text;
        expect(mysql).toContain('`credits` SMALLINT NOT NULL DEFAULT 3');
        const mssql = exportSql(sampleS1('postgresql'), 'sql_server').text;
        expect(mssql).toContain('[id] INT IDENTITY(1,1) NOT NULL');
        expect(mssql).toContain(
            '[created_at] DATETIME2 NOT NULL DEFAULT GETDATE()'
        );
        const pg = exportSql(sampleS1('mysql'), 'postgresql').text;
        expect(pg).toContain('"id" serial NOT NULL');
        expect(pg).toContain(
            '"created_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP'
        );
    });
    it('EXP-044 checks: a safe check is converted, an unsafe one listed', () => {
        const ok = exportSql(sampleS2('postgresql'), 'mysql').text;
        expect(ok).toContain('CHECK (`credits` > 0)');
    });
    it('EXP-042 a foreign key to a column that is not unique is not created', () => {
        const d = sampleS1('postgresql');
        const cust = Object.values(d.columns).find(
            (c) => c.name === 'full_name'
        )!;
        const link = Object.values(d.links.byId)[0];
        const bad = {
            ...d,
            links: {
                ...d.links,
                byId: { [link.id]: { ...link, sourceColumnId: cust.id } },
            },
        };
        const text = exportSql(bad, 'mysql').text;
        expect(text).not.toContain('ALTER TABLE `orders` ADD CONSTRAINT');
        expect(text).toContain(
            '-- not created (customers.full_name is not unique'
        );
    });
    it('EXP-048 views and empty tables are not exported, with a note', () => {
        const d = sampleS1('postgresql');
        const orders = Object.values(d.entities.byId).find(
            (e) => e.name === 'orders'
        )!;
        const asView = {
            ...d,
            entities: {
                ...d.entities,
                byId: {
                    ...d.entities.byId,
                    [orders.id]: { ...orders, kind: 'view' as const },
                },
            },
        };
        const text = exportSql(asView, 'mysql').text;
        expect(text).toContain(
            '1 view not exported: only tables are converted'
        );
        expect(text).not.toContain('CREATE TABLE `orders`');
    });
    it('EXP-003 an empty diagram gives an error and no text', () => {
        const empty = {
            ...sampleS1('postgresql'),
            entities: { byId: {}, order: [] },
        };
        const r = exportSql(empty, 'mysql');
        expect(r.text).toBe('');
        expect(r.diagnostics[0].severity).toBe('error');
    });
    it('EXP-005 MySQL to MariaDB uses the MySQL generator; MariaDB and CockroachDB are variants', () => {
        expect(exportSql(sampleS1('mysql'), 'mariadb').text).toBe(
            exportSql(sampleS1('mysql'), 'mysql').text
        );
        expect(exportSql(sampleS1('postgresql'), 'cockroachdb').text).toBe(
            exportSql(sampleS1('postgresql'), 'postgresql').text
        );
    });
    it('EXP-007 EXP-008 targets without a writer give a clear error', () => {
        for (const t of ['generic', 'oracle', 'clickhouse'] as const) {
            const r = exportSql(sampleS1('postgresql'), t);
            expect(r.text).toBe('');
            expect(r.diagnostics[0].message).toContain('not supported');
        }
        const oracleSource = {
            ...sampleS1('postgresql'),
            databaseType: 'oracle' as const,
        };
        expect(
            exportSql(oracleSource, 'mysql').diagnostics[0].message
        ).toContain('not supported');
    });
    it('EXP-001 EXP-002 only the visible tables are exported', () => {
        const d = sampleS1('postgresql');
        const customers = Object.values(d.entities.byId).find(
            (e) => e.name === 'customers'
        )!;
        const text = exportSql(d, 'postgresql', {
            filter: { tableIds: [customers.id] },
        }).text;
        expect(text).toContain('CREATE TABLE "customers"');
        expect(text).not.toContain('"orders"');
    });
    it('EXP-009 EXP-010 EXP-011 EXP-012 views, primary-key indexes, merged keys, dangling links', () => {
        const s2 = sampleS2('postgresql');
        const text = exportSql(s2, 'postgresql').text;
        expect(text.match(/CREATE (UNIQUE )?INDEX/g)).toHaveLength(1);
        const dangling = {
            ...s2,
            links: {
                ...s2.links,
                byId: {
                    x: {
                        ...Object.values(s2.links.byId)[0],
                        id: 'x',
                        sourceColumnId: 'ghost',
                    },
                },
                order: ['x'],
            },
        };
        expect(exportSql(dangling, 'postgresql').text).not.toContain(
            'FOREIGN KEY'
        );
    });
});
